        s->fd = -1;
        s->refs = 1;
        if (path && !*path) {
                path = NULL;
        }
        if (name && *name && strcmp (name, "-")) {
                if (path && *path) {
                        int plen = strlen (path);
                        int nlen = strlen (name);
                        s->dir = malloc (plen + nlen + 2);
                        if (!s->dir) {
                                free (s);
                                return NULL;
                        }
                        memcpy (s->dir, path, plen);
                        s->dir[plen] = '/';
                        memcpy (s->dir + plen + 1, name, nlen + 1);
                        s->path = strdup (path);
                } else {
                        s->dir = strdup (name);
                }
